        const contents = await readSafeContainedContractFile(workspaceRoot, contract.path);
        const digest = contents ? createHash('sha256').update(contents).digest('hex') : null;
        if (digest !== contract.sha256) {
            add('error', contract.code, `Template-owned authority file is missing, unsafe, or differs from the approved current Template bytes: ${contract.path}.`, contract.path);
        }
